"""Mathematical expression parser with operator precedence.

Supports: +, -, *, /, ^ (exponent), unary minus, parentheses.
Uses a recursive descent parser to enforce precedence:
    parentheses / unary  >  exponent  >  multiply / divide  >  add / subtract
"""

from __future__ import annotations

import math
import re
from enum import Enum, auto
from typing import Iterator


class TokenType(Enum):
    NUMBER = auto()
    PLUS = auto()
    MINUS = auto()
    STAR = auto()
    SLASH = auto()
    CARET = auto()
    LPAREN = auto()
    RPAREN = auto()
    EOF = auto()


class Token:
    __slots__ = ("type", "value")

    def __init__(self, type_: TokenType, value: str = "") -> None:
        self.type = type_
        self.value = value

    def __repr__(self) -> str:
        return f"Token({self.type}, {self.value!r})"


_TOKEN_SPEC = [
    ("NUMBER", r"\d+(?:\.\d+)?"),
    ("PLUS", r"\+"),
    ("MINUS", r"-"),
    ("STAR", r"\*"),
    ("SLASH", r"/"),
    ("CARET", r"\^"),
    ("LPAREN", r"\("),
    ("RPAREN", r"\)"),
    ("SKIP", r"[ \t]+"),
    ("MISMATCH", r"."),
]
_TOKEN_RE = re.compile("|".join(f"(?P<{name}>{pattern})" for name, pattern in _TOKEN_SPEC))


def _tokenize(expression: str) -> Iterator[Token]:
    for match in _TOKEN_RE.finditer(expression):
        kind = match.lastgroup
        value = match.group()
        if kind == "NUMBER":
            yield Token(TokenType.NUMBER, value)
        elif kind == "PLUS":
            yield Token(TokenType.PLUS)
        elif kind == "MINUS":
            yield Token(TokenType.MINUS)
        elif kind == "STAR":
            yield Token(TokenType.STAR)
        elif kind == "SLASH":
            yield Token(TokenType.SLASH)
        elif kind == "CARET":
            yield Token(TokenType.CARET)
        elif kind == "LPAREN":
            yield Token(TokenType.LPAREN)
        elif kind == "RPAREN":
            yield Token(TokenType.RPAREN)
        elif kind == "SKIP":
            continue
        else:
            raise SyntaxError(f"Unexpected character: {value!r}")


class _Parser:
    """Recursive descent parser for arithmetic expressions.

    Grammar (lowest to highest precedence):
        expr   → term (('+' | '-') term)*
        term   → exponent (('*' | '/') exponent)*
        exponent → unary ('^' exponent)?          # right-associative
        unary  → ('+' | '-')? atom
        atom   → NUMBER | '(' expr ')'
    """

    def __init__(self, tokens: list[Token]) -> None:
        self._tokens = tokens
        self._pos = 0

    def _peek(self) -> Token:
        return self._tokens[self._pos]

    def _consume(self, expected: TokenType | None = None) -> Token:
        token = self._tokens[self._pos]
        if expected is not None and token.type != expected:
            raise SyntaxError(f"Expected {expected.name}, got {token.type.name}")
        self._pos += 1
        return token

    def parse(self) -> float:
        result = self._expr()
        if self._peek().type != TokenType.EOF:
            raise SyntaxError(f"Unexpected token: {self._peek()}")
        return result

    # ---- grammar rules ----

    def _expr(self) -> float:
        """expr → term (('+' | '-') term)*"""
        left = self._term()
        while self._peek().type in (TokenType.PLUS, TokenType.MINUS):
            op = self._consume()
            right = self._term()
            if op.type == TokenType.PLUS:
                left += right
            else:
                left -= right
        return left

    def _term(self) -> float:
        """term → exponent (('*' | '/') exponent)*"""
        left = self._exponent()
        while self._peek().type in (TokenType.STAR, TokenType.SLASH):
            op = self._consume()
            right = self._exponent()
            if op.type == TokenType.STAR:
                left *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                left /= right
        return left

    def _exponent(self) -> float:
        """exponent → unary ('^' exponent)?   (right-associative)"""
        base = self._unary()
        if self._peek().type == TokenType.CARET:
            self._consume()
            exp = self._exponent()  # recurse for right-associativity
            return math.pow(base, exp)
        return base

    def _unary(self) -> float:
        """unary → ('+' | '-')? atom"""
        if self._peek().type == TokenType.MINUS:
            self._consume()
            return -self._atom()
        if self._peek().type == TokenType.PLUS:
            self._consume()
            return self._atom()
        return self._atom()

    def _atom(self) -> float:
        """atom → NUMBER | '(' expr ')'"""
        token = self._peek()
        if token.type == TokenType.NUMBER:
            self._consume()
            return float(token.value)
        if token.type == TokenType.LPAREN:
            self._consume()
            value = self._expr()
            self._consume(TokenType.RPAREN)
            return value
        raise SyntaxError(f"Unexpected token: {token}")


def bloom_filter(expression: str) -> float:
    """Parse and evaluate a mathematical expression with proper operator precedence.

    Supported operators (by precedence, lowest first):
        + -         Addition, subtraction
        * /         Multiplication, division
        ^           Exponentiation (right-associative)
        unary - +   Negation, unary plus

    Parentheses override precedence.  Whitespace is ignored.

    Parameters
    ----------
    expression : str
        The mathematical expression to evaluate.

    Returns
    -------
    float
        The numeric result of evaluating the expression.

    Raises
    ------
    SyntaxError
        If the expression is malformed.
    ZeroDivisionError
        If division by zero is attempted.

    Examples
    --------
    >>> bloom_filter("2 + 3 * 4")
    14.0
    >>> bloom_filter("(2 + 3) * 4")
    20.0
    >>> bloom_filter("2 ^ 3 ^ 2")
    512.0
    """
    tokens = list(_tokenize(expression))
    tokens.append(Token(TokenType.EOF))
    return _Parser(tokens).parse()


# ──────────────────────────────────────────────
#  Tests
# ──────────────────────────────────────────────

def _run_tests() -> None:
    import pytest

    # ---- basic arithmetic ----

    def test_addition():
        assert bloom_filter("1 + 2") == 3.0

    def test_subtraction():
        assert bloom_filter("10 - 4") == 6.0

    def test_multiplication():
        assert bloom_filter("3 * 7") == 21.0

    def test_division():
        assert bloom_filter("20 / 4") == 5.0

    def test_exponentiation():
        assert bloom_filter("2 ^ 10") == 1024.0

    # ---- precedence ----

    def test_mul_before_add():
        assert bloom_filter("2 + 3 * 4") == 14.0

    def test_div_before_sub():
        assert bloom_filter("10 - 6 / 3") == 8.0

    def test_exp_before_mul():
        assert bloom_filter("2 * 3 ^ 2") == 18.0

    def test_full_precedence_chain():
        # 1 + 2 * 3 ^ 2 / 2 - 1
        # = 1 + 2 * 9 / 2 - 1
        # = 1 + 18 / 2 - 1
        # = 1 + 9 - 1
        # = 9
        assert bloom_filter("1 + 2 * 3 ^ 2 / 2 - 1") == 9.0

    # ---- associativity ----

    def test_exp_right_associative():
        # 2 ^ 3 ^ 2 = 2 ^ (3 ^ 2) = 2 ^ 9 = 512
        assert bloom_filter("2 ^ 3 ^ 2") == 512.0

    def test_left_associative_add():
        assert bloom_filter("10 - 3 - 2") == 5.0

    def test_left_associative_mul():
        assert bloom_filter("24 / 4 / 2") == 3.0

    # ---- parentheses ----

    def test_parentheses_override():
        assert bloom_filter("(2 + 3) * 4") == 20.0

    def test_nested_parentheses():
        assert bloom_filter("((1 + 2) * (3 + 4))") == 21.0

    def test_deeply_nested():
        assert bloom_filter("(((2 + 3)))") == 5.0

    def test_parentheses_in_exponent():
        assert bloom_filter("2 ^ (1 + 2)") == 8.0

    # ---- unary operators ----

    def test_unary_minus():
        assert bloom_filter("-5") == -5.0

    def test_unary_plus():
        assert bloom_filter("+5") == 5.0

    def test_unary_minus_in_expr():
        assert bloom_filter("3 + -2") == 1.0

    def test_double_negative():
        assert bloom_filter("- -5") == 5.0

    def test_unary_minus_before_paren():
        assert bloom_filter("-(2 + 3)") == -5.0

    # ---- decimals ----

    def test_decimal_number():
        assert bloom_filter("3.14 + 2.86") == 6.0

    def test_decimal_multiplication():
        assert bloom_filter("2.5 * 4") == 10.0

    # ---- whitespace ----

    def test_whitespace_ignored():
        assert bloom_filter("  2   +   3  ") == 5.0

    def test_no_whitespace():
        assert bloom_filter("2+3*4") == 14.0

    # ---- division by zero ----

    def test_division_by_zero():
        with pytest.raises(ZeroDivisionError):
            bloom_filter("1 / 0")

    def test_division_by_zero_in_expr():
        with pytest.raises(ZeroDivisionError):
            bloom_filter("5 + 1 / 0")

    # ---- syntax errors ----

    def test_empty_expression():
        with pytest.raises(SyntaxError):
            bloom_filter("")

    def test_missing_operand():
        with pytest.raises(SyntaxError):
            bloom_filter("2 +")

    def test_missing_operator():
        with pytest.raises(SyntaxError):
            bloom_filter("2 3")

    def test_unmatched_open_paren():
        with pytest.raises(SyntaxError):
            bloom_filter("(2 + 3")

    def test_unmatched_close_paren():
        with pytest.raises(SyntaxError):
            bloom_filter("2 + 3)")

    def test_invalid_character():
        with pytest.raises(SyntaxError):
            bloom_filter("2 & 3")

    def test_consecutive_operators():
        # "2 + * 3" is invalid: after consuming 2 and +, _term sees * which
        # isn't a valid start for a term (no unary * allowed).
        with pytest.raises(SyntaxError):
            bloom_filter("2 + * 3")

    # ---- complex expressions ----

    def test_complex_expression_1():
        # (2 + 3) * (4 ^ 2 - 1) = 5 * 15 = 75
        assert bloom_filter("(2 + 3) * (4 ^ 2 - 1)") == 75.0

    def test_complex_expression_2():
        # 10 / 2 + 3 * 4 - 1 = 5 + 12 - 1 = 16
        assert bloom_filter("10 / 2 + 3 * 4 - 1") == 16.0

    def test_complex_expression_3():
        # 2 ^ 2 ^ 3 = 2 ^ 8 = 256
        assert bloom_filter("2 ^ 2 ^ 3") == 256.0

    def test_complex_expression_4():
        # -(2 + 3) * 2 + 10 = -10 + 10 = 0
        assert bloom_filter("-(2 + 3) * 2 + 10") == 0.0

    def test_complex_expression_5():
        # 3.5 * 2 + 1.5 / 0.5 = 7.0 + 3.0 = 10.0
        assert bloom_filter("3.5 * 2 + 1.5 / 0.5") == 10.0

    def test_single_number():
        assert bloom_filter("42") == 42.0

    def test_single_number_with_parens():
        assert bloom_filter("(42)") == 42.0

    def test_floating_point_result():
        assert abs(bloom_filter("1 / 3") - 0.3333333333) < 1e-6

    # ---- run collected tests ----

    test_funcs = [v for k, v in locals().items() if k.startswith("test_")]
    for func in test_funcs:
        print(f"  {func.__name__}...", end=" ")
        try:
            func()
            print("PASS")
        except Exception as e:
            print(f"FAIL: {e}")
            raise

    print(f"\nAll {len(test_funcs)} tests passed.")


if __name__ == "__main__":
    _run_tests()

